def _now_iso() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def _sse(payload: Dict[str, Any]) -> str:
    return "data: " + json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n\n"


def _truncate(s: Any, n: int) -> str:
    if not isinstance(s, str) or n <= 0:
        return ""
    return s if len(s) <= n else s[:n]


def _sanitize_text(s: Any, max_len: int) -> str:
    if not isinstance(s, str):
        return ""
    s2 = s.replace("\r\n", "\n").replace("\r", "\n").strip()
    if max_len > 0 and len(s2) > max_len:
        return s2[:max_len]
    return s2


def _safe_equal(a: str, b: str) -> bool:
    if not isinstance(a, str) or not isinstance(b, str):
        return False
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))


def _get_client_ip() -> str:
    xff = request.headers.get("X-Forwarded-For", "")
    if xff:
        ip = xff.split(",")[0].strip()
        if ip:
            return ip[:128]
    ip2 = request.remote_addr or request.environ.get("REMOTE_ADDR") or "unknown"
    return str(ip2)[:128]


def _normalize_domains(domains: Any) -> Optional[List[str]]:
    if not isinstance(domains, list):
        return None
    out: List[str] = []
    for d in domains:
        if not isinstance(d, str):
            continue
        dd = d.strip().lower()
        if not dd:
            continue
        if "://" in dd:
            dd = dd.split("://", 1)[1]
        dd = dd.split("/", 1)[0]
        if dd and dd not in out:
            out.append(dd)
    return out[:50] if out else None


def _validate_date_yyyy_mm_dd(s: Any) -> Optional[str]:
    if not isinstance(s, str):
        return None
    ss = s.strip()
    if not ss:
        return None
    try:
        datetime.strptime(ss, "%Y-%m-%d")
        return ss
    except ValueError:
        return None


def _coerce_search_type(s: Any) -> str:
    if not isinstance(s, str):
        return "auto"
    ss = s.strip().lower()
    if ss == "keyword":
        return "fast"
    if ss in ("auto", "neural", "fast", "deep"):
        return ss
    return "auto"


def _coerce_category(s: Any) -> Optional[str]:
    if not isinstance(s, str):
        return None
    ss = s.strip()
    if not ss:
        return None
    allowed = {"news", "research paper", "company", "tweet", "financial report", "personal site", "people"}
    return ss if ss in allowed else None


def _coerce_int(v: Any, default: int, min_v: int, max_v: int) -> int:
    try:
        i = int(v)
    except Exception:
        return default
    if i < min_v:
        return min_v
    if i > max_v:
        return max_v
    return i


def search_web_exa(
    queries: List[str],
    search_type: str = "auto",
    include_domains: Optional[List[str]] = None,
    exclude_domains: Optional[List[str]] = None,
    start_published_date: Optional[str] = None,
    end_published_date: Optional[str] = None,
    start_crawl_date: Optional[str] = None,
    end_crawl_date: Optional[str] = None,
    category: Optional[str] = None
) -> Dict[str, Any]:
    if not isinstance(queries, list):
        return {"total_results": 0, "returned_results": 0, "results": [], "errors": ["queries_not_list"]}

    cleaned: List[str] = []
    seen_q: set = set()
    for q in queries[:EXA_MAX_QUERIES]:
        if not isinstance(q, str):
            continue
        qq = q.strip()
        if not qq or qq in seen_q:
            continue
        seen_q.add(qq)
        cleaned.append(qq)

    if not cleaned:
        return {"total_results": 0, "returned_results": 0, "results": [], "errors": ["no_valid_queries"]}

    stype = _coerce_search_type(search_type)
    inc = _normalize_domains(include_domains)
    exc = _normalize_domains(exclude_domains)
    spd = _validate_date_yyyy_mm_dd(start_published_date)
    epd = _validate_date_yyyy_mm_dd(end_published_date)
    cat = _coerce_category(category)

    ret_per_query = _coerce_int(EXA_RETURN_RESULTS_PER_QUERY, 25, 1, 100)
    ret_total = _coerce_int(EXA_RETURN_RESULTS_TOTAL, 150, 1, 2000)
    highlights_per_url = _coerce_int(EXA_HIGHLIGHTS_PER_URL, 3, 1, 10)
    highlight_sentences = _coerce_int(EXA_HIGHLIGHT_SENTENCES, 2, 1, 10)
    max_age_hours = _coerce_int(EXA_MAX_AGE_HOURS, 168, -1, 87600)

    results: List[Dict[str, Any]] = []
    errors: List[str] = []
    seen_urls: set = set()

    for q in cleaned:
        if len(results) >= ret_total:
            break

        params: Dict[str, Any] = {
            "query": q,
            "num_results": EXA_RESULTS_PER_QUERY,
            "type": stype,
            "contents": {
                "summary": {"query": q},
                "highlights": {"query": q, "num_sentences": highlight_sentences, "highlights_per_url": highlights_per_url},
                "max_age_hours": max_age_hours
            }
        }

        if inc:
            params["include_domains"] = inc
        if exc:
            params["exclude_domains"] = exc
        if spd:
            params["start_published_date"] = spd
        if epd:
            params["end_published_date"] = epd
        if isinstance(start_crawl_date, str) and start_crawl_date.strip():
            params["start_crawl_date"] = start_crawl_date.strip()
        if isinstance(end_crawl_date, str) and end_crawl_date.strip():
            params["end_crawl_date"] = end_crawl_date.strip()
        if cat:
            params["category"] = cat

        try:
            res = exa_client.search(**params)
            rlist = getattr(res, "results", None)
            if not isinstance(rlist, list):
                errors.append("exa_no_results_list")
                continue

            added = 0
            for item in rlist:
                if len(results) >= ret_total or added >= ret_per_query:
                    break

                if isinstance(item, dict):
                    url = _sanitize_text(item.get("url", ""), 2048)
                    title = _sanitize_text(item.get("title", ""), 512)
                    published_date_val = item.get("published_date", None) or item.get("publishedDate", None)
                    author_val = item.get("author", None)
                    score_val = item.get("score", None)
                    summary_val = item.get("summary", None)
                    highlights_val = item.get("highlights", [])
                else:
                    url = _sanitize_text(getattr(item, "url", ""), 2048)
                    title = _sanitize_text(getattr(item, "title", ""), 512)
                    published_date_val = getattr(item, "published_date", None)
                    author_val = getattr(item, "author", None)
                    score_val = getattr(item, "score", None)
                    summary_val = getattr(item, "summary", None)
                    highlights_val = getattr(item, "highlights", [])

                if not url or url in seen_urls:
                    continue
                seen_urls.add(url)

                highlights: List[str] = []
                if isinstance(highlights_val, list):
                    for h in highlights_val[:5]:
                        hs = _sanitize_text(h, 800)
                        if hs:
                            highlights.append(hs)

                published_date_s: Optional[str] = None
                if isinstance(published_date_val, str):
                    published_date_s = _sanitize_text(published_date_val, 64)

                author_s: Optional[str] = None
                if isinstance(author_val, str):
                    author_s = _sanitize_text(author_val, 128)

                score_f: Optional[float] = None
                try:
                    if isinstance(score_val, (int, float)):
                        score_f = float(score_val)
                except Exception:
                    score_f = None

                summary_s: str = ""
                if isinstance(summary_val, str):
                    summary_s = _sanitize_text(summary_val, EXA_SUMMARY_MAX_CHARS)

                results.append({
                    "query": q,
                    "title": title,
                    "url": url,
                    "published_date": published_date_s,
                    "author": author_s,
                    "score": score_f,
                    "summary": summary_s,
                    "highlights": highlights
                })
                added += 1
        except Exception as e:
            logger.error("EXA search failed: %s", str(e), exc_info=True)
            errors.append("exa_search_failed")

    return {"total_results": len(results), "returned_results": len(results), "results": results, "errors": errors}


def _supermemory_headers() -> Dict[str, str]:
    return {"Authorization": f"Bearer {SUPERMEMORY_API_KEY}", "Content-Type": "application/json"}


def _supermemory_container_tag(session_id: str, user_id: Optional[str], ip: str) -> str:
    base = f"{SUPERMEMORY_CONTAINER_PREFIX}:{(user_id or 'anon')}:{session_id}:{ip}"
    allowed: List[str] = []
    for ch in base:
        o = ord(ch)
        if (48 <= o <= 57) or (65 <= o <= 90) or (97 <= o <= 122) or ch in (":", "-", "_", ".", "/"):
            allowed.append(ch)
        else:
            allowed.append("_")
    tag = "".join(allowed).strip(":")
    if not tag:
        tag = f"{SUPERMEMORY_CONTAINER_PREFIX}:anon"
    if len(tag) > 128:
        tag = tag[:128]
    return tag


def _supermemory_add_document(container_tag: str, title: str, content: str, metadata: Dict[str, Any]) -> None:
    if not SUPERMEMORY_API_KEY or not SUPERMEMORY_STORE_ENABLED:
        return
    content2 = _sanitize_text(content, SUPERMEMORY_STORE_MAX_CHARS)
    if not content2:
        return
    url = SUPERMEMORY_BASE_URL.rstrip("/") + "/v3/documents"
    payload = {"title": _sanitize_text(title, 200) or "chat", "content": content2, "tags": [container_tag], "metadata": metadata}
    try:
        r = requests.post(url, headers=_supermemory_headers(), data=json.dumps(payload, ensure_ascii=False), timeout=60)
        if r.status_code >= 400:
            logger.error("Supermemory add failed: %s %s", r.status_code, r.text[:800])
    except Exception as e:
        logger.error("Supermemory add exception: %s", str(e), exc_info=True)


def _supermemory_search(container_tag: str, query: str) -> List[Dict[str, Any]]:
    if not SUPERMEMORY_API_KEY or not SUPERMEMORY_SEARCH_ENABLED:
        return []
    q = _sanitize_text(query, 4000)
    if not q:
        return []
    url = SUPERMEMORY_BASE_URL.rstrip("/") + "/v4/search"
    payload = {"query": q, "limit": SUPERMEMORY_SEARCH_LIMIT, "tags": [container_tag]}
    try:
        r = requests.post(url, headers=_supermemory_headers(), data=json.dumps(payload, ensure_ascii=False), timeout=60)
        if r.status_code >= 400:
            logger.error("Supermemory search failed: %s %s", r.status_code, r.text[:800])
            return []
        obj = r.json()
        results = obj.get("results", [])
        if not isinstance(results, list):
            return []
        out: List[Dict[str, Any]] = []
        for it in results[:SUPERMEMORY_SEARCH_LIMIT]:
            if not isinstance(it, dict):
                continue
            text = it.get("text") or it.get("content") or it.get("memory") or ""
            out.append({
                "id": it.get("id"),
                "score": it.get("score"),
                "title": it.get("title"),
                "text": _sanitize_text(text, SUPERMEMORY_RESULT_TEXT_MAX_CHARS),
                "source": it.get("source"),
                "url": it.get("url")
            })
        return out
    except Exception as e:
        logger.error("Supermemory search exception: %s", str(e), exc_info=True)
        return []


def _is_rate_limit_error(err: BaseException) -> bool:
    try:
        sc = getattr(err, "status_code", None)
        if isinstance(sc, int) and sc == 429:
            return True
    except Exception:
        pass
    try:
        resp = getattr(err, "response", None)
        sc2 = getattr(resp, "status_code", None)
        if isinstance(sc2, int) and sc2 == 429:
            return True
    except Exception:
        pass
    s = str(err).lower()
    return ("429" in s) or ("too many requests" in s) or ("rate limit" in s)


def _is_retryable_error(err: BaseException) -> bool:
    if _is_rate_limit_error(err):
        return True
    s = str(err).lower()
    return ("timeout" in s) or ("temporarily" in s) or ("connection" in s) or ("reset" in s) or ("502" in s) or ("503" in s) or ("504" in s)


def _next_cerebras_key() -> str:
    global _cerebras_idx
    with _cerebras_idx_lock:
        k = CEREBRAS_KEYS[_cerebras_idx % len(CEREBRAS_KEYS)]
        _cerebras_idx = (_cerebras_idx + 1) % len(CEREBRAS_KEYS)
        return k


def _cerebras_stream_create(params: Dict[str, Any]) -> Any:
    last_err: Optional[BaseException] = None
    attempts = max(1, len(CEREBRAS_KEYS))
    for _ in range(attempts):
        key = _next_cerebras_key()
        client = Cerebras(api_key=key)
        try:
            try:
                return client.chat.completions.create(**params)
            except TypeError as e:
                msg = str(e)
                if "max_completion_tokens" in msg and "unexpected" in msg:
                    p2 = dict(params)
                    mct = p2.pop("max_completion_tokens", None)
                    if mct is not None:
                        p2["max_tokens"] = mct
                    return client.chat.completions.create(**p2)
                if "max_tokens" in msg and "unexpected" in msg:
                    p2 = dict(params)
                    mt = p2.pop("max_tokens", None)
                    if mt is not None:
                        p2["max_completion_tokens"] = mt
                    return client.chat.completions.create(**p2)
                raise
        except Exception as e:
            last_err = e
            if _is_retryable_error(e):
                time.sleep(0.6)
                continue
            break
    if last_err:
        raise last_err
    raise RuntimeError("Cerebras request failed")


def _normalize_history(raw: Any) -> List[Dict[str, Any]]:
    if not isinstance(raw, list):
        return []
    out: List[Dict[str, Any]] = []
    total_chars = 0
    for msg in raw[-MAX_HISTORY_MESSAGES:]:
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role not in ("user", "assistant"):
            continue
        content = _sanitize_text(msg.get("content", ""), MAX_MESSAGE_CHARS)
        if not content:
            continue
        if total_chars + len(content) > MAX_HISTORY_CHARS_TOTAL:
            break
        total_chars += len(content)
        out.append({"role": role, "content": content})
    return out


def _append_tool_messages(messages: List[Dict[str, Any]], tool_calls: List[Dict[str, Any]], tool_outputs: List[Dict[str, Any]]) -> None:
    messages.append({"role": "assistant", "content": "", "tool_calls": tool_calls})
    messages.extend(tool_outputs)


@app.after_request
def _headers(resp: Response) -> Response:
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "DENY"
    resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    resp.headers["Cache-Control"] = resp.headers.get("Cache-Control", "no-store")
    resp.headers["Access-Control-Allow-Origin"] = "*"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
    return resp


@app.route("/", methods=["GET"])
def index() -> Response:
    return Response("OK", mimetype="text/plain; charset=utf-8")


@app.route("/chat", methods=["POST", "OPTIONS"])
def chat() -> Response:
    if request.method == "OPTIONS":
        return Response("", status=204)

    if APP_API_KEY:
        auth = request.headers.get("Authorization", "")
        tok = ""
        if auth.startswith("Bearer "):
            tok = auth[7:].strip()
        else:
            tok = auth.strip()
        if not _safe_equal(tok, APP_API_KEY):
            return Response("Unauthorized", status=401, mimetype="text/plain; charset=utf-8")

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return Response("Invalid JSON", status=400, mimetype="text/plain; charset=utf-8")

    user_message = _sanitize_text(data.get("message", ""), MAX_MESSAGE_CHARS)
    if not user_message:
        return Response("Message required", status=400, mimetype="text/plain; charset=utf-8")

    enable_search = data.get("enable_search", False)
    if isinstance(enable_search, str):
        enable_search = enable_search.strip().lower() == "true"
    enable_search = bool(enable_search)

    session_id = _sanitize_text(data.get("session_id", ""), 128) or str(uuid.uuid4())
    user_id = _sanitize_text(data.get("user_id", ""), 128) or None
    history = _normalize_history(data.get("history", []))

    ip = _get_client_ip()
    container_tag = _supermemory_container_tag(session_id, user_id, ip)

    memory_hits: List[Dict[str, Any]] = []
    if SUPERMEMORY_SEARCH_ENABLED and SUPERMEMORY_API_KEY:
        memory_hits = _supermemory_search(container_tag, user_message)

    messages: List[Dict[str, Any]] = [{"role": "system", "content": SYSTEM_PROMPT}]
    if memory_hits:
        messages.append({"role": "system", "content": "SUPERMEMORY_CONTEXT_JSON=" + json.dumps({"results": memory_hits}, ensure_ascii=False, separators=(",", ":"))})
    if history:
        messages.extend(history)
    messages.append({"role": "user", "content": user_message})

    def generate() -> Generator[str, None, None]:
        yield _sse({"type": "info", "content": "connected", "ts": _now_iso()})

        assistant_text_parts: List[str] = []
        tool_round = 0

        while True:
            tool_round += 1
            if tool_round > max(1, MAX_TOOL_ROUNDS):
                break

            params: Dict[str, Any] = {
                "messages": messages,
                "model": MODEL_ID,
                "stream": True,
                "temperature": TEMPERATURE,
                "top_p": TOP_P,
                "max_completion_tokens": MAX_COMPLETION_TOKENS
            }

            if enable_search:
                params["tools"] = TOOLS
                params["tool_choice"] = "auto"

            try:
                stream = _cerebras_stream_create(params)
            except Exception as e:
                logger.error("Cerebras create failed: %s", str(e), exc_info=True)
                yield _sse({"type": "error", "content": "Cerebras hiba."})
                yield "data: [DONE]\n\n"
                return

            tool_calls_buffer: Dict[int, Dict[str, Any]] = {}
            finished_reason: Optional[str] = None

            try:
                for chunk in stream:
                    choices = getattr(chunk, "choices", None)
                    if not isinstance(choices, list) or not choices:
                        continue
                    choice0 = choices[0]
                    delta = getattr(choice0, "delta", None)
                    if delta is None:
                        delta = getattr(choice0, "message", None)

                    if delta is not None:
                        reasoning = getattr(delta, "reasoning", None)
                        if isinstance(reasoning, str) and reasoning:
                            yield _sse({"type": "reasoning", "content": reasoning})

                        content = getattr(delta, "content", None)
                        if isinstance(content, str) and content:
                            assistant_text_parts.append(content)
                            yield _sse({"type": "content", "content": content})

                        tool_calls = getattr(delta, "tool_calls", None)
                        if isinstance(tool_calls, list) and tool_calls:
