                                if not isinstance(idx, int):
                                    idx = 0
                                if idx not in tool_calls_buffer:
                                    tool_calls_buffer[idx] = {"id": getattr(tc, "id", ""), "type": getattr(tc, "type", "function"), "function": {"name": "", "arguments": ""}}
                                fn = getattr(tc, "function", None)
                                if fn is not None:
                                    name = getattr(fn, "name", None)
                                    if isinstance(name, str) and name:
                                        tool_calls_buffer[idx]["function"]["name"] = name
                                    args = getattr(fn, "arguments", None)
                                    if isinstance(args, str) and args:
                                        tool_calls_buffer[idx]["function"]["arguments"] += args

                    fr = getattr(choice0, "finish_reason", None)
                    if isinstance(fr, str) and fr:
                        finished_reason = fr
                        if fr == "tool_calls":
                            break
